// Keep a visible scene pointer independent of WebGL initialization.
(()=>{const surface=document.getElementById('workspace'),cursor=document.getElementById('sceneCursor');const unlock=()=>{if(document.pointerLockElement&&document.exitPointerLock)document.exitPointerLock();};unlock();document.addEventListener('pointerlockchange',unlock);window.addEventListener('focus',unlock);surface.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;cursor.hidden=false;cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px';});surface.addEventListener('pointerleave',()=>{cursor.hidden=true;});window.addEventListener('blur',()=>{cursor.hidden=true;});})();
